-- Hyprland config (plain, no HyDE). Based on /usr/share/hypr/hyprland.lua
-- Wiki: https://wiki.hypr.land/Configuring/Start/

------------------
---- MONITORS ----
------------------

-- Fallback for any monitor not listed in monitors.lua
hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })
-- Your layout (generated by nwg-displays)
require("monitors")

---------------------
---- MY PROGRAMS ----
---------------------

local terminal    = "kitty"
local fileManager = "dolphin"
local browser     = "firefox"
local editor      = "code"
local menu        = "rofi -show drun"

-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("waybar")
    hl.exec_cmd("dunst")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("sleep 1 && waypaper --restore")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)

-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
hl.env("MOZ_ENABLE_WAYLAND", "1")

-----------------------
---- LOOK AND FEEL ----
-----------------------

-- Border colors generated by matugen (waypaper -> matugen -> colors.lua); Nord fallback
local ok, matugen_col = pcall(dofile, os.getenv("HOME") .. "/.config/hypr/colors.lua")
if not ok then
    matugen_col = {
        active_border   = { colors = {"rgba(88c0d0ee)", "rgba(5e81acee)"}, angle = 45 },
        inactive_border = "rgba(4c566aaa)",
    }
end

hl.config({
    general = {
        gaps_in     = 4,
        gaps_out    = 8,
        border_size = 2,
        col = matugen_col,
        resize_on_border = true,
        allow_tearing    = false,
        layout           = "dwindle",
    },

    decoration = {
        rounding       = 8,
        rounding_power = 2,
        active_opacity   = 1.0,
        inactive_opacity = 1.0,
        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },
        blur = {
            enabled  = true,
            size     = 3,
            passes   = 1,
            vibrancy = 0.1696,
        },
    },

    animations = { enabled = true },

    dwindle = { preserve_split = true },
    master  = { new_status = "master" },

    misc = {
        force_default_wallpaper = 0,
        disable_hyprland_logo   = true,
    },

    input = {
        kb_layout    = "fr",
        follow_mouse = 1,
        sensitivity  = 0,
        touchpad = { natural_scroll = false },
    },
})

hl.curve("easeOutQuint", { type = "bezier", points = { {0.23, 1},  {0.32, 1} } })
hl.curve("linear",       { type = "bezier", points = { {0, 0},     {1, 1}    } })
hl.curve("almostLinear", { type = "bezier", points = { {0.5, 0.5}, {0.75, 1} } })
hl.curve("quick",        { type = "bezier", points = { {0.15, 0},  {0.1, 1}  } })
hl.curve("easy",         { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })

hl.animation({ leaf = "global",     enabled = true, speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",     enabled = true, speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",    enabled = true, speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn",  enabled = true, speed = 4.1,  spring = "easy",   style = "popin 87%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.49, bezier = "linear", style = "popin 87%" })
hl.animation({ leaf = "fade",       enabled = true, speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers",     enabled = true, speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" })

hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

---------------------
---- KEYBINDINGS ----
---------------------
-- Kept close to HyDE's defaults so muscle memory still works.

local mod = "SUPER"

-- Apps
hl.bind(mod .. " + T",     hl.dsp.exec_cmd(terminal), { description = "Terminal" })
hl.bind(mod .. " + RETURN", hl.dsp.exec_cmd(terminal), { description = "Terminal" })
hl.bind(mod .. " + E",     hl.dsp.exec_cmd(fileManager), { description = "File manager" })
hl.bind(mod .. " + B",     hl.dsp.exec_cmd(browser), { description = "Browser" })
hl.bind(mod .. " + C",     hl.dsp.exec_cmd(editor), { description = "Code editor" })
hl.bind(mod .. " + A",     hl.dsp.exec_cmd("pkill -x rofi || " .. menu), { description = "App launcher" })
hl.bind(mod .. " + R",     hl.dsp.exec_cmd("pkill -x rofi || " .. menu), { description = "App launcher" })
hl.bind(mod .. " + TAB",   hl.dsp.exec_cmd("pkill -x rofi || rofi -show window"), { description = "Switch window (rofi)" })
hl.bind(mod .. " + V",     hl.dsp.exec_cmd("pkill -x rofi || cliphist list | rofi -dmenu -p clipboard | cliphist decode | wl-copy"), { description = "Clipboard history" })
hl.bind("CTRL + SHIFT + ESCAPE", hl.dsp.exec_cmd(terminal .. " -e top"), { description = "Task manager (top)" })

-- Session
hl.bind(mod .. " + L",           hl.dsp.exec_cmd("loginctl lock-session"), { description = "Lock screen" })
hl.bind("CTRL + ALT + DELETE",   hl.dsp.exec_cmd("wlogout"), { description = "Logout menu" })
hl.bind(mod .. " + Delete",      hl.dsp.exit(), { description = "Exit Hyprland" })

-- Windows
hl.bind(mod .. " + Q",           hl.dsp.window.close(), { description = "Close window" })
hl.bind("ALT + F4",              hl.dsp.window.close(), { description = "Close window" })
hl.bind(mod .. " + W",           hl.dsp.window.float({ action = "toggle" }), { description = "Toggle floating" })
hl.bind(mod .. " + F",           hl.dsp.window.fullscreen(), { description = "Fullscreen" })
hl.bind(mod .. " + SHIFT + F",   hl.dsp.window.pin(), { description = "Pin window (all workspaces)" })
hl.bind(mod .. " + P",           hl.dsp.window.pseudo(), { description = "Pseudo-tile" })
hl.bind(mod .. " + J",           hl.dsp.layout("togglesplit"), { description = "Toggle split direction" })
hl.bind(mod .. " + G",           hl.dsp.group.toggle(), { description = "Toggle group" })
hl.bind("ALT + TAB",             hl.dsp.window.cycle_next(), { description = "Cycle windows" })

-- Focus
hl.bind(mod .. " + left",  hl.dsp.focus({ direction = "left" }), { description = "Focus left" })
hl.bind(mod .. " + right", hl.dsp.focus({ direction = "right" }), { description = "Focus right" })
hl.bind(mod .. " + up",    hl.dsp.focus({ direction = "up" }), { description = "Focus up" })
hl.bind(mod .. " + down",  hl.dsp.focus({ direction = "down" }), { description = "Focus down" })

-- Move windows
hl.bind(mod .. " + SHIFT + CTRL + left",  hl.dsp.window.move({ direction = "l" }), { description = "Move window left" })
hl.bind(mod .. " + SHIFT + CTRL + right", hl.dsp.window.move({ direction = "r" }), { description = "Move window right" })
hl.bind(mod .. " + SHIFT + CTRL + up",    hl.dsp.window.move({ direction = "u" }), { description = "Move window up" })
hl.bind(mod .. " + SHIFT + CTRL + down",  hl.dsp.window.move({ direction = "d" }), { description = "Move window down" })

-- Resize windows
hl.bind(mod .. " + SHIFT + left",  hl.dsp.window.resize({ x = -30, y = 0,   relative = true }), { repeating = true, description = "Shrink width" })
hl.bind(mod .. " + SHIFT + right", hl.dsp.window.resize({ x = 30,  y = 0,   relative = true }), { repeating = true, description = "Grow width" })
hl.bind(mod .. " + SHIFT + up",    hl.dsp.window.resize({ x = 0,   y = -30, relative = true }), { repeating = true, description = "Shrink height" })
hl.bind(mod .. " + SHIFT + down",  hl.dsp.window.resize({ x = 0,   y = 30,  relative = true }), { repeating = true, description = "Grow height" })

-- Mouse: SUPER + left drag = move, SUPER + right drag = resize
hl.bind(mod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true, description = "Move window (drag)" })
hl.bind(mod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true, description = "Resize window (drag)" })

-- Workspaces. The number row is bound twice: digits (US) and AZERTY keysyms,
-- so SUPER + 1..0 works whatever the layout.
local azerty = { "ampersand", "eacute", "quotedbl", "apostrophe", "parenleft",
                 "minus", "egrave", "underscore", "ccedilla", "agrave" }
for i = 1, 10 do
    for _, key in ipairs({ tostring(i % 10), azerty[i] }) do
        local d = key == tostring(i % 10) and ("Go to workspace " .. i) or nil
        hl.bind(mod .. " + " .. key,         hl.dsp.focus({ workspace = i }),        { description = d })
        hl.bind(mod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }), { description = d and ("Move window to workspace " .. i) })
    end
end
hl.bind(mod .. " + CTRL + right", hl.dsp.focus({ workspace = "r+1" }), { description = "Next workspace" })
hl.bind(mod .. " + CTRL + left",  hl.dsp.focus({ workspace = "r-1" }), { description = "Previous workspace" })
hl.bind(mod .. " + CTRL + down",  hl.dsp.focus({ workspace = "empty" }), { description = "First empty workspace" })
hl.bind(mod .. " + mouse_down",   hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
hl.bind(mod .. " + mouse_up",     hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })

-- Scratchpad
hl.bind(mod .. " + S",         hl.dsp.workspace.toggle_special("magic"), { description = "Toggle scratchpad" })
hl.bind(mod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }), { description = "Send window to scratchpad" })

-- Screenshots (saved to ~/Pictures/Screenshots and copied to clipboard)
local shot = 'f=~/Pictures/Screenshots/$(date +%F_%H-%M-%S).png; '
hl.bind(mod .. " + SHIFT + P", hl.dsp.exec_cmd(shot .. 'grim -g "$(slurp)" "$f" && wl-copy < "$f" && notify-send "Screenshot" "$f"'), { description = "Screenshot region" })
hl.bind("Print",               hl.dsp.exec_cmd(shot .. 'grim "$f" && wl-copy < "$f" && notify-send "Screenshot" "$f"'), { description = "Screenshot full screen" })
hl.bind(mod .. " + Print",     hl.dsp.exec_cmd(shot .. 'grim -g "$(slurp)" "$f" && wl-copy < "$f" && notify-send "Screenshot" "$f"'), { description = "Screenshot region" })
hl.bind(mod .. " + ALT + P",   hl.dsp.exec_cmd("hyprpicker -an"), { description = "Color picker" })

-- Screen recording (toggle: press once to start, again to stop) -> ~/Videos/Recordings
hl.bind(mod .. " + SHIFT + R",         hl.dsp.exec_cmd("~/.config/hypr/scripts/screenrec.sh"), { description = "Screen recorder (start/stop)" })
hl.bind("CTRL + SHIFT + ALT + R",      hl.dsp.exec_cmd("~/.config/hypr/scripts/screenrec.sh"), { description = "Screen recorder (start/stop)" })

-- Media / hardware keys
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true, description = "Volume up" })
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true, description = "Volume down" })
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, description = "Mute" })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, description = "Mute microphone" })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true, description = "Brightness up" })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true, description = "Brightness down" })
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true, description = "Next track" })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play / pause" })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play / pause" })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true, description = "Previous track" })

-- Waypaper
hl.bind(mod .. " + SHIFT + W",  function() hl.exec_cmd("waypaper") end, { description = "Wallpaper picker" })

-- Keybind cheatsheet (lists every bind with a description)
hl.bind(mod .. " + H", hl.dsp.exec_cmd("~/.config/hypr/scripts/keybinds.sh"), { description = "Show keybinds" })

--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})

hl.window_rule({
    name  = "float-dialogs",
    match = { class = "^(pavucontrol|org.pulseaudio.pavucontrol|blueman-manager|nm-connection-editor|nwg-look|nwg-displays|qt5ct|qt6ct|kvantummanager)$" },
    float = true,
})

   -- Rofi blur
   hl.layer_rule({
       match = { namespace = "rofi" },
       blur = true,
       ignore_alpha = 0,
   })
